.alert.info, .alert.notice, .flash.info, .flash.notice { background-color: rgb(234, 244, 249); border-color: rgb(40, 141, 193); color: rgb(28, 99, 135); }

.alert.success, .flash.success { background-color: rgb(234, 247, 239); border-color: rgb(43, 175, 95); color: rgb(23, 123, 65); }

.alert.warning, .flash.warning { background-color: rgb(253, 249, 237); border-color: rgb(230, 175, 0); color: rgb(138, 105, 0); }

.alert.error, .flash.error { background-color: rgb(250, 240, 240); border-color: rgb(206, 101, 101); color: rgb(145, 70, 70); }

.alert.alert-full-width-top, .flash.alert-full-width-top { border-top: 0px; border-left: 0px; border-right: 0px; }

.alert.alert-full-width-bottom, .flash.alert-full-width-bottom { border-bottom: 0px; border-left: 0px; border-right: 0px; }

